# Example for page "main": draw once, then update in a loop.
# Generated by ESP UI Builder; replace the demo part with your own code.

import time

import ui_display
import ui_main

ui = ui_main.UI(ui_display.create())
p = dict(ui_main.DEFAULTS)
ui.draw(p)

# Demo: sweep "humidity" and print how long update() takes.
LO, HI = 0, 100
step = max(1, (HI - LO) // 50)
while True:
    value = p["humidity"] + step
    if value > HI or value < LO:
        step = -step
        value = p["humidity"] + step
    p["humidity"] = value
    t0 = time.ticks_us()
    ui.update(p)
    print("update: %d us" % time.ticks_diff(time.ticks_us(), t0))
    time.sleep_ms(200)
